<template>
  <view class="detail-page">
    <view class="detail-header"><button @click="back">‹</button><text>灵感详情</text><button class="share-button" open-type="share">↗</button></view>
    <view v-if="loading" class="detail-skeleton"><view/><text/><text/></view>
    <view v-else-if="error" class="detail-state"><text>加载失败</text><small>{{ error }}</small><button @click="load">重试</button></view>
    <template v-else-if="detail">
      <view class="result-preview"><video v-if="item.contentType==='video'" :src="item.resultUrl||item.coverUrl" :poster="item.coverUrl" controls :autoplay="false" object-fit="cover"/><AppImage v-else :src="item.resultUrl||item.coverUrl" :fallback="item.coverUrl" :alt="item.title" width="100%" height="100%" radius="0"/><text class="ai-badge">AI生成示例</text></view>
      <view class="content-card"><view class="title-row"><view><text class="type-label">{{ typeLabel }}</text><text class="title">{{ item.title }}</text></view><button :class="{active:item.favorite}" @click="toggleFavorite">{{ item.favorite?'♥':'♡' }} {{ item.favoriteCount }}</button></view><text class="description">{{ item.description }}</text><view class="usage-row"><text>浏览 {{ item.viewCount }}</text><text>使用 {{ item.useCount }}</text><text>生成 {{ item.generateCount }}</text></view></view>
      <view class="content-card"><view class="card-head"><text>完整提示词</text><button @click="copyPrompt">复制</button></view><text class="prompt-text">{{ item.prompt }}</text><template v-if="item.negativePrompt"><text class="field-label">负面提示词</text><text class="negative-text">{{ item.negativePrompt }}</text></template></view>
      <view class="content-card"><text class="card-title">生成配置</text><view class="parameter-list"><view><text>模型</text><strong>{{ resolvedModel || '自动选择' }}</strong></view><view v-for="entry in parameterEntries" :key="entry[0]"><text>{{ parameterLabel(entry[0]) }}</text><strong>{{ entry[1] }}</strong></view></view><view v-if="!detail.modelAvailable" class="model-note">原模型已下架，生成时将自动切换为兼容模型 {{ detail.compatibleModelId || '系统默认模型' }}</view></view>
      <view class="safe-space"/>
      <view class="fixed-action"><button class="copy-action" @click="copyPrompt">复制提示词</button><button class="generate-action" :loading="using" @click="generateSame">生成同款</button></view>
    </template>
  </view>
</template>
<script setup lang="ts">
import{computed,ref}from"vue";import{onLoad,onShareAppMessage}from"@dcloudio/uni-app";import AppImage from"../../components/AppImage.vue";import{inspirationAPI}from"../../features/inspiration/api";import{saveInspirationDraft}from"../../features/inspiration/draft";import type{InspirationDetailResponse}from"../../features/inspiration/types";import{hasValidToken,requireAuth}from"../../features/auth/gate";
const templateId=ref(""),detail=ref<InspirationDetailResponse|null>(null),loading=ref(true),using=ref(false),error=ref("");const item=computed(()=>detail.value!.item),typeLabel=computed(()=>({image:"AI图片",video:"AI视频",ppt:"PPT方案"}[item.value.contentType])),resolvedModel=computed(()=>detail.value?.modelAvailable?item.value.modelId:detail.value?.compatibleModelId),parameterEntries=computed(()=>Object.entries(item.value.parameters||{}).filter(([,value])=>value!==undefined&&value!==null&&value!==""));
async function load(){loading.value=true;error.value="";try{detail.value=await inspirationAPI.detail(templateId.value)}catch(reason){error.value=reason instanceof Error?reason.message:"请稍后重试"}finally{loading.value=false}}
function parameterLabel(key:string){return({ratio:"画面比例",quality:"清晰度",duration:"视频时长",resolution:"分辨率",pageCount:"PPT页数",scenario:"使用场景",style:"视觉风格",language:"语言",withImages:"包含图片"}as Record<string,string>)[key]||key}
async function ensureLogin(action:"copy"|"favorite"|"generate",resume:()=>void|Promise<void>){if(hasValidToken()){await resume();return true}const protectedAction=action==="generate"?(item.value.contentType==="video"?"generate_video":item.value.contentType==="ppt"?"generate_ppt":"generate_image"):"save_work";await requireAuth({action:protectedAction,route:"/pages/inspiration/InspirationDetailPage",payload:{templateId:templateId.value,action},resume});return false}
async function copyPrompt(){await ensureLogin("copy",async()=>{await inspirationAPI.event(templateId.value,"copy_prompt");uni.setClipboardData({data:String(item.value.prompt||""),success:()=>uni.showToast({title:"提示词已复制",icon:"success"})})})}
async function toggleFavorite(){await ensureLogin("favorite",async()=>{const next=!item.value.favorite;await inspirationAPI.favorite(templateId.value,next);item.value.favorite=next;item.value.favoriteCount=Math.max(0,item.value.favoriteCount+(next?1:-1));uni.showToast({title:next?"已收藏":"已取消收藏",icon:"success"})})}
async function generateSame(){if(using.value)return;await ensureLogin("generate",async()=>{using.value=true;try{const latest=await inspirationAPI.detail(templateId.value);saveInspirationDraft(latest);await inspirationAPI.event(templateId.value,"use_template");if(!latest.modelAvailable)uni.showToast({title:"原模型已下架，已切换兼容模型",icon:"none",duration:2200});const route=latest.item.contentType==="video"?"/pages/user/UserVideoCreationPage":latest.item.contentType==="ppt"?"/packagePpt/pages/create":"/pages/user/UserImageCreationPage";uni.navigateTo({url:`${route}?templateId=${encodeURIComponent(templateId.value)}`})}catch(reason){uni.showToast({title:reason instanceof Error?reason.message:"暂时无法使用该模板",icon:"none"})}finally{using.value=false}})}
function back(){uni.navigateBack({fail:()=>uni.switchTab({url:"/pages/user/UserHomePage"})})}onLoad(options=>{templateId.value=String(options?.templateId||"").trim();if(!templateId.value){error.value="模板参数缺失";loading.value=false;return}void load()});onShareAppMessage(()=>({title:item.value?.title||"知启云AI创作灵感",path:`/pages/inspiration/InspirationDetailPage?templateId=${encodeURIComponent(templateId.value)}`,imageUrl:item.value?.coverUrl}));
</script>
<style scoped>
.detail-page{min-height:100vh;color:#171c2d;background:#f5f6fa}.detail-header{position:sticky;z-index:10;top:0;display:grid;height:calc(50px + env(safe-area-inset-top));padding:env(safe-area-inset-top) 14px 0;box-sizing:border-box;grid-template-columns:42px 1fr 42px;align-items:center;background:rgba(255,255,255,.96)}.detail-header text{text-align:center;font-size:16px;font-weight:700}.detail-header button,.title-row button,.card-head button,.detail-state button,.fixed-action button{margin:0;padding:0;border:0}.detail-header button::after,.title-row button::after,.card-head button::after,.detail-state button::after,.fixed-action button::after{display:none}.detail-header button{background:transparent;font-size:30px}.share-button{font-size:20px!important}.result-preview{position:relative;height:410px;background:#e9edf5}.result-preview video{width:100%;height:100%}.ai-badge{position:absolute;z-index:4;right:14px;bottom:14px;padding:6px 9px;border-radius:5px;color:#fff;background:rgba(18,24,43,.72);font-size:10px}.content-card{margin:12px 14px 0;padding:17px;border:1px solid #e8eaf1;border-radius:8px;background:#fff}.title-row,.card-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.type-label,.title,.description,.field-label,.prompt-text,.negative-text,.card-title{display:block}.type-label{color:#4a6cff;font-size:10px;font-weight:650}.title{margin-top:4px;font-size:20px;font-weight:750;line-height:28px}.title-row button{width:auto;height:36px;padding:0 11px;border-radius:18px;color:#727c91;background:#f3f5fa;font-size:12px}.title-row button.active{color:#f04e64;background:#fff0f2}.description{margin-top:10px;color:#737c90;font-size:12px;line-height:20px}.usage-row{display:flex;margin-top:14px;gap:18px;color:#9299aa;font-size:10px}.card-head text,.card-title{font-size:15px;font-weight:700}.card-head button{width:auto;color:#4a6cff;background:transparent;font-size:12px}.prompt-text,.negative-text{margin-top:13px;color:#384055;font-size:13px;line-height:22px;white-space:pre-wrap}.field-label{margin-top:18px;color:#7c8497;font-size:11px}.negative-text{margin-top:7px;color:#6e7689}.parameter-list{display:grid;margin-top:12px;grid-template-columns:1fr 1fr;gap:10px}.parameter-list view{padding:11px;border-radius:6px;background:#f7f8fb}.parameter-list text,.parameter-list strong{display:block}.parameter-list text{color:#8b93a5;font-size:9px}.parameter-list strong{margin-top:4px;font-size:12px;word-break:break-all}.model-note{margin-top:12px;padding:10px;border-radius:6px;color:#976500;background:#fff7df;font-size:10px;line-height:17px}.safe-space{height:96px}.fixed-action{position:fixed;z-index:12;right:0;bottom:0;left:0;display:grid;padding:11px 16px calc(11px + env(safe-area-inset-bottom));grid-template-columns:1fr 1.6fr;gap:10px;background:rgba(255,255,255,.97);box-shadow:0 -6px 22px rgba(25,32,57,.08)}.fixed-action button{height:46px;border-radius:23px;font-size:14px;font-weight:650}.copy-action{color:#4a6cff;background:#edf1ff}.generate-action{color:#fff;background:#4a6cff}.detail-skeleton,.detail-state{display:flex;min-height:500px;align-items:center;justify-content:center;flex-direction:column}.detail-skeleton view{width:100%;height:360px;background:#e8ebf2}.detail-skeleton text{width:80%;height:18px;margin-top:16px;background:#e8ebf2}.detail-state small{margin-top:8px;color:#8b93a5}.detail-state button{width:auto;margin-top:16px;padding:0 18px;border-radius:18px;color:#fff;background:#4a6cff}</style>
